+/**
+ * KS-2166 — four kyc routes act on a user named by the caller (a path or a body field) and, before this change, never
+ * compared that user with the signed-in caller. Any signed-in caller could read, list, erase or start another
+ * person's identity verification.
+ *
+ * The rule pinned here (Wednesday's ruling on Seat A 29th's plan, 2026-11-12):
+ *   - GET /api/kyc/:id            the subject (verification.userId, after the lookup) or a platform role;
+ *   - GET /api/kyc/user/:userId   the subject (:userId) or a platform role;
+ *   - DELETE /api/kyc/user/:userId/data   the subject only (no platform exception: irreversible);
+ *   - POST /api/kyc/initiate      the subject named by the BODY's userId only (the consent recorded is theirs).
+ *   "The subject" means the caller's `req.user.userId` and the subject's id are both non-empty strings and equal after an
+ *   ASCII-only case fold (A to Z lowered, nothing else). "A platform role" is the shared isPlatformRole (SYSTEM_ADMIN,
+ *   SUPER_ADMIN, ASCII fold, a non-string refused: KS-1591).
+ *   A refusal is 403 { success: false, error: { code: 'FORBIDDEN', message: 'Forbidden' } }. On the list, DELETE and
+ *   initiate it comes before any statement (initiate: after the body parse); on GET /:id it follows the lookup only.
+ *
+ * Harness: the KS-1845 one (an in-memory table, `authenticate` replaced by a stand-in that sets whatever principal a
+ * cell names, a real HTTP listener on 127.0.0.1), plus a recorder of every statement and every consent row so a cell
+ * can assert that a refused call read, wrote and erased nothing. The rate limiter (KS-2166 D5: unchanged, first on
+ * initiate) is not under test here, so its budget is raised before the service is imported.
+ */
+import { describe, it, expect, vi, beforeAll, beforeEach, afterAll } from 'vitest';
+import http from 'http';
+
+process.env.KYC_PROVIDER = 'mock';
+process.env.NODE_ENV = 'test';
+process.env.KYC_RATE_LIMIT_PER_HOUR = '100000';
+
+const TABLE = new Map<string, Record<string, any>>();
+const CONSENTS: any[][] = [];
+/** Every statement the service issues, with its parameters. */
+const SQLS: { sql: string; params: any[] }[] = [];
+const COLS = [
+  'id', 'user_id', 'requested_level', 'current_level', 'status', 'provider',
+  'provider_application_id', 'provider_check_id', 'documents', 'liveness_completed',
+  'liveness_score', 'checks', 'overall_score', 'risk_level', 'reviewed_by',
+  'review_notes', 'consent_given', 'consent_timestamp', 'data_retention_expiry',
+  'created_at', 'updated_at', 'completed_at', 'expires_at',
+];
+
+vi.mock('../db', () => ({
+  initDb: async () => undefined,
+  isDbAvailable: () => true,
+  query: async (sql: string, params: any[] = []) => {
+    const s = String(sql);
+    SQLS.push({ sql: s.replace(/\s+/g, ' ').trim(), params });
+    if (/^\s*DELETE\s+FROM\s+svc_kyc_verifications/i.test(s)) {
+      let n = 0;
+      for (const [k, r] of TABLE) if (r.user_id === params[0]) { TABLE.delete(k); n++; }
+      return { rows: [], rowCount: n };
+    }
+    if (/^\s*DELETE/i.test(s)) return { rows: [], rowCount: 0 };
+    if (/INSERT\s+INTO\s+svc_kyc_verifications/i.test(s)) {
+      const row: Record<string, any> = {};
+      COLS.forEach((c, i) => { row[c] = params[i]; });
+      TABLE.set(row.id, row);
+      return { rows: [] };
+    }
+    if (/INSERT\s+INTO\s+svc_kyc_consents/i.test(s)) { CONSENTS.push(params); return { rows: [] }; }
+    if (/FROM\s+svc_kyc_verifications\s+WHERE\s+id\s*=/i.test(s)) {
+      const row = TABLE.get(params[0]);
+      return { rows: row ? [{ ...row }] : [] };
+    }
+    if (/FROM\s+svc_kyc_verifications\s+WHERE\s+user_id\s*=/i.test(s)) {
+      return { rows: [...TABLE.values()].filter((r) => r.user_id === params[0]).map((r) => ({ ...r })) };
+    }
+    if (/COUNT\(\*\)/i.test(s)) return { rows: [{ cnt: String(TABLE.size) }] };
+    return { rows: [], rowCount: 0 };
+  },
+}));
+
+vi.mock('../subjectDeks', () => ({
+  subjectDeks: {
+    getOrCreateDek: async () => Buffer.alloc(32, 7),
+    getDek: async () => Buffer.alloc(32, 7),
+    evict: () => undefined,
+  },
+}));
+
+/** The principal `authenticate` puts on the request; `undefined` leaves req.user unset. */
+let PRINCIPAL: Record<string, unknown> | undefined;
+
+vi.mock('@secuura/shared', async (importOriginal) => {
+  const actual = await importOriginal<Record<string, unknown>>();
+  return {
+    ...actual,
+    encryptFieldWithDek: (plain: string) => plain,
+    isEncryptedPii: () => false,
+    isSubjectDekCiphertext: () => false,
+    authenticate: () => (req: any, _res: any, next: any) => {
+      if (PRINCIPAL !== undefined) req.user = { ...PRINCIPAL };
+      next();
+    },
+  };
+});
+
+vi.mock('express', async (importOriginal) => {
+  const actual: any = (await importOriginal<any>()).default ?? (await importOriginal<any>());
+  const factory: any = (...args: any[]) => {
+    const app = actual(...args);
+    app.listen = () => ({ close: (cb?: () => void) => cb?.(), address: () => ({ port: 0 }), on() { return this; } });
+    return app;
+  };
+  Object.assign(factory, actual);
+  return { ...actual, default: factory };
+});
+
+let server: http.Server;
+let base: string;
+
+async function boot() {
+  if (server) return;
+  const app = (await import('../index')).default as any;
+  server = http.createServer(app);
+  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', () => resolve()));
+  base = `http://127.0.0.1:${(server.address() as any).port}`;
+}
+
+async function call(method: string, path: string, body?: unknown) {
+  const r = await fetch(base + path, {
+    method,
+    headers: { 'Content-Type': 'application/json' },
+    body: body === undefined ? undefined : JSON.stringify(body),
+  });
+  const text = await r.text();
+  let parsed: any;
+  try { parsed = JSON.parse(text); } catch { parsed = text; }
+  return { status: r.status, body: parsed };
+}
+
+const SUBJECT = 'a3f1c2de-4b5a-4c6d-8e7f-0123456789ab';
+const OTHER = 'b4e2d3cf-5c6b-4d7e-9f80-123456789abc';
+const FIXED_ID = 'c5f3e4d0-6d7c-4e8f-a091-23456789abcd';
+const SECOND_ID = 'd6a4f5e1-7e8d-4f90-b1a2-3456789abcde';
+const NOW = '2026-11-12T00:00:00.000Z';
+const FORBIDDEN = { success: false, error: { code: 'FORBIDDEN', message: 'Forbidden' } };
+const INITIATE = (userId: unknown, consentGiven = true) => ({ userId, requestedLevel: 'BASIC', consentGiven });
+
+/** A verification stored as the real upsert would store it, with fixed ids and times so an answer is deterministic. */
+function seed(user: string | null = SUBJECT, id = FIXED_ID): string {
+  TABLE.set(id, {
+    id, user_id: user, requested_level: 'HIGH', current_level: 'NONE', status: 'pending',
+    provider: 'mock', provider_application_id: null, provider_check_id: null, documents: null,
+    liveness_completed: false, liveness_score: null, checks: '[]', overall_score: null, risk_level: null,
+    reviewed_by: null, review_notes: null, consent_given: true, consent_timestamp: NOW,
+    data_retention_expiry: null, created_at: NOW, updated_at: NOW, completed_at: null, expires_at: null,
+  });
+  return id;
+}
+
+/** The answer formatVerificationResponse gives for a seeded row (the same object the route served before KS-2166). */
+const RECORD = (id: string, user: string) => ({
+  id, userId: user, requestedLevel: 'HIGH', currentLevel: 'NONE', status: 'pending', provider: 'mock',
+  documentsSubmitted: 0, livenessCompleted: false, checks: [], riskLevel: null, createdAt: NOW, updatedAt: NOW,
+});
+
+const as = (role: unknown, userId: unknown = OTHER) => ({ userId, role, tenantId: 'ks2166-tenant' });
+const statements = () => SQLS.map((x) => x.sql);
+const deletes = () => SQLS.filter((x) => /^DELETE/i.test(x.sql));
+
+/** The four routes, each with how a cell reaches it for a given subject id. */
+const ROUTES = {
+  'GET /api/kyc/:id': (subject: string) => { seed(subject); return call('GET', `/api/kyc/${FIXED_ID}`); },
+  'GET /api/kyc/user/:userId': (subject: string) => { seed(subject); return call('GET', `/api/kyc/user/${encodeURIComponent(subject)}`); },
+  'DELETE /api/kyc/user/:userId/data': (subject: string) => { seed(subject); return call('DELETE', `/api/kyc/user/${encodeURIComponent(subject)}/data`); },
+  'POST /api/kyc/initiate': (subject: string) => call('POST', '/api/kyc/initiate', INITIATE(subject)),
+} as const;
+type RouteName = keyof typeof ROUTES;
+const ALL = Object.keys(ROUTES) as RouteName[];
+const READS: RouteName[] = ['GET /api/kyc/:id', 'GET /api/kyc/user/:userId'];
+const OWNER_ONLY: RouteName[] = ['DELETE /api/kyc/user/:userId/data', 'POST /api/kyc/initiate'];
+
+/** What a refused call may have done: on GET /:id the one lookup by id; elsewhere nothing at all. */
+function expectRefusedAndInert(route: RouteName, r: { status: number; body: any }) {
+  expect(r.status).toBe(403);
+  expect(r.body).toEqual(FORBIDDEN);
+  expect(deletes()).toHaveLength(0);
+  expect(CONSENTS).toHaveLength(0);
+  if (route === 'GET /api/kyc/:id') {
+    expect(statements()).toEqual(['SELECT * FROM svc_kyc_verifications WHERE id = $1']);
+  } else {
+    expect(statements()).toEqual([]);
+  }
+  if (route === 'POST /api/kyc/initiate') expect(TABLE.size).toBe(0);
+  else expect(TABLE.size).toBe(1);
+}
+
+afterAll(async () => {
+  if (server) await new Promise<void>((resolve) => server.close(() => resolve()));
+});
+
+describe('KS-2166 — the four kyc routes act only for the signed-in subject (or, on the two reads, a platform role)', () => {
+  // The first import of index.ts is a cold boot of the whole service: its own budget, as KS-1845's.
+  beforeAll(async () => {
+    await boot();
+  }, 120_000);
+
+  beforeEach(() => {
+    TABLE.clear();
+    CONSENTS.length = 0;
+    SQLS.length = 0;
+    PRINCIPAL = undefined;
+  });
+
+  // R: a signed-in caller who is not the subject (an ordinary role) is refused, and the refusal reads, writes and erases nothing.
+  it.each(ALL)('RED ks2166 R %s refuses a signed-in caller who is not the subject', async (route) => {
+    PRINCIPAL = as('OWNER', OTHER);
+    const r = await ROUTES[route](SUBJECT);
+    expectRefusedAndInert(route, r);
+  });
+
+  // C: the subject is served exactly as before the change.
+  it('control ks2166 C GET /api/kyc/:id serves the subject their record, unchanged', async () => {
+    PRINCIPAL = as('OWNER', SUBJECT);
+    seed();
+    const r = await call('GET', `/api/kyc/${FIXED_ID}`);
+    expect(r.status).toBe(200);
+    expect(r.body).toEqual({ success: true, data: RECORD(FIXED_ID, SUBJECT) });
+  });
+
+  it('control ks2166 C GET /api/kyc/user/:userId serves the subject their list, unchanged', async () => {
+    PRINCIPAL = as('OWNER', SUBJECT);
+    seed(SUBJECT, FIXED_ID);
+    seed(SUBJECT, SECOND_ID);
+    const r = await call('GET', `/api/kyc/user/${SUBJECT}`);
+    expect(r.status).toBe(200);
+    expect(r.body).toEqual({
+      success: true,
+      data: { userId: SUBJECT, currentLevel: 'BASIC', verifications: [RECORD(FIXED_ID, SUBJECT), RECORD(SECOND_ID, SUBJECT)], count: 2 },
+    });
+  });
+
+  it('control ks2166 C DELETE /api/kyc/user/:userId/data still erases for the subject, unchanged', async () => {
+    PRINCIPAL = as('OWNER', SUBJECT);
+    seed();
+    const r = await call('DELETE', `/api/kyc/user/${SUBJECT}/data`);
+    expect(r.status).toBe(200);
+    expect(r.body).toEqual({ success: true, message: 'All KYC data for user has been deleted.', deletedVerifications: 1 });
+    expect(deletes().map((d) => d.params[0])).toEqual([SUBJECT, SUBJECT, SUBJECT]);
+    expect(TABLE.size).toBe(0);
+  });
+
+  it('control ks2166 C POST /api/kyc/initiate still starts a verification and records consent for the subject', async () => {
+    PRINCIPAL = as('OWNER', SUBJECT);
+    const r = await call('POST', '/api/kyc/initiate', INITIATE(SUBJECT));
+    expect(r.status).toBe(201);
+    expect(r.body.success).toBe(true);
+    expect(Object.keys(r.body.data).sort()).toEqual(['expiresAt', 'providerApplicationId', 'requestedLevel', 'requiredSteps', 'status', 'verificationId']);
+    expect([...TABLE.values()].map((v) => v.user_id)).toEqual([SUBJECT]);
+    expect(CONSENTS.map((c) => c[1])).toEqual([SUBJECT]);
+  });
+
+  // A: the platform exception. Admitted on the two reads, refused on DELETE and initiate.
+  const PLATFORM = ['SYSTEM_ADMIN', 'SUPER_ADMIN', 'system_admin'];
+  it.each(READS.flatMap((route) => PLATFORM.map((role) => [route, role] as const)))(
+    'ks2166 A %s admits a platform role (%s) reading another user', async (route, role) => {
+      PRINCIPAL = as(role, OTHER);
+      const r = await ROUTES[route](SUBJECT);
+      expect(r.status).toBe(200);
+      if (route === 'GET /api/kyc/:id') expect(r.body.data).toEqual(RECORD(FIXED_ID, SUBJECT));
+      else expect(r.body.data.count).toBe(1);
+    });
+
+  it.each(OWNER_ONLY.flatMap((route) => PLATFORM.map((role) => [route, role] as const)))(
+    'RED ks2166 A %s refuses a platform role (%s) acting for another user (owner only)', async (route, role) => {
+      PRINCIPAL = as(role, OTHER);
+      const r = await ROUTES[route](SUBJECT);
+      expectRefusedAndInert(route, r);
+    });
+
+  // Every role that is not a platform role, and no principal at all, is refused on all four.
+  const NOT_PLATFORM: [string, Record<string, unknown> | undefined][] = [
+    ['ADMIN', as('ADMIN')],
+    ['ORG_ADMIN', as('ORG_ADMIN')],
+    ['ISSUER_ADMIN', as('ISSUER_ADMIN')],
+    ['connector', as('connector', 'connector:api-key')],
+    ['an array role', as(['SYSTEM_ADMIN'])],
+    ['no role', as(undefined)],
+    ['no principal at all', undefined],
+  ];
+  it.each(ALL.flatMap((route) => NOT_PLATFORM.map(([label, p]) => [route, label, p] as const)))(
+    'RED ks2166 A %s refuses %s', async (route, _label, p) => {
+      PRINCIPAL = p;
+      const r = await ROUTES[route](SUBJECT);
+      expectRefusedAndInert(route, r);
+    });
+
+  // I: identity edges. A caller who cannot be shown to be anyone is refused, even when the subject is empty too.
+  const NO_IDENTITY: [string, unknown][] = [['a missing userId', undefined], ['a numeric userId', 42], ['an array userId', [SUBJECT]], ['an empty userId', '']];
+  it.each(ALL.flatMap((route) => NO_IDENTITY.map(([label, id]) => [route, label, id] as const)))(
+    'RED ks2166 I %s refuses %s', async (route, _label, id) => {
+      PRINCIPAL = as('OWNER', id);
+      const r = await ROUTES[route](SUBJECT);
+      expectRefusedAndInert(route, r);
+    });
+
+  it('RED ks2166 I GET /api/kyc/:id refuses an empty caller id against a record with an empty subject', async () => {
+    PRINCIPAL = as('OWNER', '');
+    seed('');
+    const r = await call('GET', `/api/kyc/${FIXED_ID}`);
+    expect(r.status).toBe(403);
+    expect(r.body).toEqual(FORBIDDEN);
+  });
+
+  // The fold: a UUID's hex is case-insensitive, so the subject spelled in the other case is still the subject.
+  it.each(ALL.flatMap((route) => [
+    [route, 'a lower-case claim, the subject in UPPER case', SUBJECT, SUBJECT.toUpperCase()],
+    [route, 'an UPPER-case claim, the subject in lower case', SUBJECT.toUpperCase(), SUBJECT],
+  ] as const))('ks2166 I %s admits %s', async (route, _label, claim, subject) => {
+    PRINCIPAL = as('OWNER', claim);
+    const r = await ROUTES[route](subject);
+    expect(r.status).toBe(route === 'POST /api/kyc/initiate' ? 201 : 200);
+  });
+
+  // The fold is ASCII only: U+212A KELVIN SIGN lower-cases to 'k' under toLowerCase(), so a Unicode fold would admit it.
+  it.each(['GET /api/kyc/:id', 'GET /api/kyc/user/:userId', 'DELETE /api/kyc/user/:userId/data'] as RouteName[])(
+    'RED ks2166 I %s refuses a subject that equals the caller only under a Unicode fold', async (route) => {
+      PRINCIPAL = as('OWNER', 'kyc-k-subject');
+      const r = await ROUTES[route]('KYC-K-SUBJECT');
+      expectRefusedAndInert(route, r);
+    });
+
+  // On initiate the row and the consent keep the BODY's spelling: the subject is the body's userId, not the caller's.
+  it('ks2166 I POST /api/kyc/initiate keys the row and the consent by the body userId, not by the caller id', async () => {
+    PRINCIPAL = as('OWNER', SUBJECT);
+    const r = await call('POST', '/api/kyc/initiate', INITIATE(SUBJECT.toUpperCase()));
+    expect(r.status).toBe(201);
+    expect([...TABLE.values()].map((v) => v.user_id)).toEqual([SUBJECT.toUpperCase()]);
+    expect(CONSENTS.map((c) => c[1])).toEqual([SUBJECT.toUpperCase()]);
+  });
+
+  // Paths as Express 4 hands them over: a percent-encoded spelling of the subject's id is decoded to the same id.
